import { GoogleGenAI, Type, Schema } from "@google/genai";
import { SYSTEM_PROMPT, CrystalAnalysis } from "../types";

const apiKey = process.env.API_KEY || '';

// Define the response schema explicitly for Gemini 3
const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    momentReading: { type: Type.STRING },
    interestLevel: { type: Type.STRING, enum: ["Baixo", "Médio", "Alto", "Oscilante"] },
    emotion: { type: Type.STRING },
    dynamic: { type: Type.STRING },
    risk: { type: Type.STRING },
    detectedMode: { type: Type.STRING },
    responses: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          type: { type: Type.STRING },
          text: { type: Type.STRING }
        },
        required: ["type", "text"]
      }
    },
    rhythm: { type: Type.STRING, enum: ["Agora", "Esperar", "Mudar assunto", "Sumir", "Encerrar"] }
  },
  required: ["momentReading", "interestLevel", "emotion", "dynamic", "risk", "detectedMode", "responses", "rhythm"]
};

export const analyzeContent = async (
  text: string, 
  imageBase64?: string
): Promise<CrystalAnalysis> => {
  if (!apiKey) {
    throw new Error("API Key not found in environment.");
  }

  const ai = new GoogleGenAI({ apiKey });

  // Use gemini-3-pro-preview for multimodal (images) or complex reasoning, 
  // flash for pure text if we wanted speed, but for "Human Attraction OS" quality matters.
  // Given we might have screenshots, let's stick to a capable model.
  const model = "gemini-3-pro-preview"; 

  const parts: any[] = [];

  if (imageBase64) {
    // Remove data URL prefix if present for the API call
    const cleanBase64 = imageBase64.split(',')[1] || imageBase64;
    parts.push({
      inlineData: {
        mimeType: "image/jpeg", // Assuming JPEG for simplicity, or detect from base64 header
        data: cleanBase64
      }
    });
  }

  if (text) {
    parts.push({ text });
  }

  if (parts.length === 0) {
    throw new Error("No content to analyze.");
  }

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: parts
      },
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.7, // Balance between creativity and analysis
      }
    });

    const responseText = response.text;
    if (!responseText) throw new Error("Empty response from Crystal Prime.");

    const analysis = JSON.parse(responseText) as CrystalAnalysis;
    return analysis;

  } catch (error) {
    console.error("Crystal Prime Error:", error);
    throw error;
  }
};

