import React from 'react';
import { Copy, Check } from 'lucide-react';

interface ResponseOption {
  type: string;
  text: string;
}

interface ResponseOptionsProps {
  responses: ResponseOption[];
}

const ResponseOptions: React.FC<ResponseOptionsProps> = ({ responses }) => {
  const [copiedIndex, setCopiedIndex] = React.useState<number | null>(null);

  const handleCopy = (text: string, index: number) => {
    navigator.clipboard.writeText(text);
    setCopiedIndex(index);
    setTimeout(() => setCopiedIndex(null), 2000);
  };

  return (
    <div className="space-y-3">
      <h3 className="text-xs font-mono text-gray-500 uppercase tracking-wider mb-2">Respostas Prontas</h3>
      {responses.map((res, idx) => (
        <div 
          key={idx} 
          className="group relative bg-crystal-900 border border-crystal-700 hover:border-crystal-glow/50 rounded-lg p-3 transition-all duration-300"
        >
          <div className="flex justify-between items-start mb-1">
            <span className="text-[10px] font-mono text-crystal-accent uppercase opacity-80">{res.type}</span>
            <button 
              onClick={() => handleCopy(res.text, idx)}
              className="text-gray-500 hover:text-white transition-colors"
              title="Copiar"
            >
              {copiedIndex === idx ? <Check size={14} className="text-green-500" /> : <Copy size={14} />}
            </button>
          </div>
          <p className="text-gray-200 font-medium select-all">{res.text}</p>
        </div>
      ))}
    </div>
  );
};

export default ResponseOptions;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeContent } from './services/gemini';
import { Message, ProcessingState, CrystalAnalysis } from './types';
import AnalysisView from './components/AnalysisView';
import ResponseOptions from './components/ResponseOptions';
import { Send, Upload, ImageIcon, X, Trash2, Infinity as InfinityIcon } from 'lucide-react';

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);
  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  };

  useEffect(() => {
    scrollToBottom();
  }, [messages, status]);

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleClearImage = () => {
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
  };

  const handleReset = () => {
    setMessages([]);
    setInputText('');
    handleClearImage();
    setStatus(ProcessingState.IDLE);
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if ((!inputText.trim() && !selectedImage) || status !== ProcessingState.IDLE) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      image: selectedImage || undefined,
      timestamp: Date.now(),
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    handleClearImage();
    setStatus(ProcessingState.ANALYZING);

    try {
      const analysis = await analyzeContent(newMessage.content || '', newMessage.image);

      const responseMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        analysis: analysis,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, responseMessage]);
      setStatus(ProcessingState.IDLE);
    } catch (error) {
      console.error(error);
      setStatus(ProcessingState.ERROR);
      // Add error message to chat
       const errorMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "Erro de conexão com o sistema central. Tente novamente.",
        timestamp: Date.now(),
      };
      setMessages(prev => [...prev, errorMessage]);
      setTimeout(() => setStatus(ProcessingState.IDLE), 3000);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#050505] text-gray-100 font-sans overflow-hidden">

      {/* HEADER */}
      <header className="flex-none border-b border-crystal-800 bg-[#0a0a0a]/90 backdrop-blur-md z-10 px-4 py-4 flex justify-between items-center">
        <div className="flex items-center space-x-3">
          <div className="relative">
            <InfinityIcon className="text-crystal-glow animate-pulse-slow" size={28} />
            <div className="absolute inset-0 blur-lg bg-crystal-accent opacity-20"></div>
          </div>
          <div>
            <h1 className="text-lg font-bold tracking-widest font-mono text-white">
              CRYSTAL PRIME
            </h1>
            <p className="text-[10px] text-gray-500 font-mono tracking-wide">HUMAN ATTRACTION OS ∞</p>
          </div>
        </div>
        <button 
          onClick={handleReset}
          className="text-gray-600 hover:text-red-400 transition-colors p-2"
          title="Reset System"
        >
          <Trash2 size={18} />
        </button>
      </header>

      {/* CHAT AREA */}
      <main 
        ref={chatContainerRef}
        className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth"
      >
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center opacity-30 pointer-events-none">
            <InfinityIcon size={64} className="text-gray-700 mb-4" />
            <p className="font-mono text-sm text-center">SISTEMA ONLINE<br/>AGUARDANDO INPUT</p>
          </div>
        )}

        {messages.map((msg) => (
          <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-fade-in-up`}>

            {/* User Message */}
            {msg.role === 'user' && (
              <div className="max-w-[85%] sm:max-w-[70%]">
                 {msg.image && (
                  <div className="mb-2 rounded-lg overflow-hidden border border-crystal-700 shadow-lg">
                    <img src={msg.image} alt="Upload" className="max-w-full max-h-64 object-cover" />
                  </div>
                )}
                {msg.content && (
                  <div className="bg-crystal-700 text-gray-200 px-4 py-2 rounded-2xl rounded-tr-sm inline-block shadow-md">
                    <p className="text-sm whitespace-pre-wrap">{msg.content}</p>
                  </div>
                )}
                <span className="text-[10px] text-gray-600 mt-1 block text-right font-mono">INPUT RECEBIDO</span>
              </div>
            )}

            {/* AI Analysis Message */}
            {msg.role === 'assistant' && (
              <div className="w-full max-w-md">
                <div className="flex items-center space-x-2 mb-2">
                  <div className="w-2 h-2 bg-crystal-glow rounded-full animate-pulse"></div>
                  <span className="text-[10px] font-mono text-crystal-glow uppercase">Análise Concluída</span>
                </div>

                {msg.content ? (
                   // Error or simple text fallback
                   <div className="bg-red-900/20 border border-red-900/50 text-red-200 px-4 py-3 rounded-lg">
                     {msg.content}
                   </div>
                ) : msg.analysis && (
                  <>
                    <AnalysisView analysis={msg.analysis} />
                    <ResponseOptions responses={msg.analysis.responses} />
                  </>
                )}
              </div>
            )}
          </div>
        ))}

        {/* Loading Indicator */}
        {status !== ProcessingState.IDLE && status !== ProcessingState.ERROR && (
           <div className="flex flex-col items-start space-y-2 animate-pulse">
             <div className="flex items-center space-x-2 text-crystal-accent">
               <div className="w-2 h-2 bg-current rounded-full animate-bounce"></div>
               <div className="w-2 h-2 bg-current rounded-full animate-bounce delay-100"></div>
               <div className="w-2 h-2 bg-current rounded-full animate-bounce delay-200"></div>
             </div>
             <span className="text-[10px] font-mono text-gray-500 uppercase tracking-wider">
               {status === ProcessingState.ANALYZING ? 'Lendo padrões...' : 'Calculando resposta...'}
             </span>
           </div>
        )}
      </main>

      {/* INPUT AREA */}
      <footer className="flex-none p-4 bg-[#0a0a0a] border-t border-crystal-800">
        <div className="max-w-4xl mx-auto flex flex-col space-y-3">

          {selectedImage && (
            <div className="flex items-center bg-crystal-900 p-2 rounded-lg border border-crystal-700 w-fit">
              <img src={selectedImage} alt="Preview" className="h-10 w-10 object-cover rounded mr-3" />
              <span className="text-xs text-gray-400 font-mono">Imagem anexada</span>
              <button onClick={handleClearImage} className="ml-3 text-gray-500 hover:text-white">
                <X size={16} />
              </button>
            </div>
          )}

          <form onSubmit={handleSubmit} className="flex items-center space-x-3">
            <input 
              type="file" 
              accept="image/*" 
              ref={fileInputRef}
              onChange={handleImageUpload}
              className="hidden" 
            />

            <button 
              type="button" 
              onClick={() => fileInputRef.current?.click()}
              className="p-3 rounded-full bg-crystal-800 text-gray-400 hover:text-crystal-glow hover:bg-crystal-700 transition-all border border-transparent hover:border-crystal-700"
              disabled={status !== ProcessingState.IDLE}
            >
              <ImageIcon size={20} />
            </button>

            <div className="flex-1 relative">
              <input
                type="text"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                placeholder={selectedImage ? "Adicione contexto (opcional)..." : "Cole o texto ou print..."}
                className="w-full bg-crystal-900 text-white placeholder-gray-600 rounded-xl py-3 px-4 border border-crystal-800 focus:border-crystal-glow focus:ring-1 focus:ring-crystal-glow focus:outline-none transition-all font-sans text-sm"
                disabled={status !== ProcessingState.IDLE}
              />
            </div>

            <button 
              type="submit" 
              className={`p-3 rounded-full transition-all flex items-center justify-center ${
                (!inputText && !selectedImage) || status !== ProcessingState.IDLE
                  ? 'bg-crystal-800 text-gray-600 cursor-not-allowed' 
                  : 'bg-crystal-glow text-white shadow-[0_0_15px_rgba(167,139,250,0.3)] hover:bg-crystal-accent hover:scale-105'
              }`}
              disabled={(!inputText && !selectedImage) || status !== ProcessingState.IDLE}
            >
              <Send size={20} className={status !== ProcessingState.IDLE ? 'opacity-0' : 'opacity-100'} />
              {status !== ProcessingState.IDLE && (
                 <div className="absolute w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>
              )}
            </button>
          </form>

          <div className="text-center">
            <p className="text-[10px] text-gray-700 font-mono uppercase tracking-widest">
              Crystal Prime v1.0 • Awaiting Input
            </p>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

