// Tab Definitions with Colors and Icons
const TABS: { id: CrystalMode; label: string; icon: React.FC<any>; color: string; desc: string }[] = [
  { id: 'STORY_REPLY', label: 'Story Reply', icon: Camera, color: 'text-blue-400', desc: 'Reação a Stories' },
  { id: 'FIRST_CONTACT', label: '1º Contato', icon: MessageCircle, color: 'text-green-400', desc: 'Abrir conversa' },
  { id: 'FLOWING', label: 'Fluindo', icon: Zap, color: 'text-yellow-400', desc: 'Manter conversa' },
  { id: 'VALUE_TEST', label: 'Teste Valor', icon: ShieldAlert, color: 'text-orange-400', desc: 'Responder desafios' },
