    <div className="flex flex-col h-screen bg-[#050505] text-gray-100 font-sans overflow-hidden">

      {/* HEADER */}
      <header className="flex-none bg-[#0a0a0a] z-10 pt-4 pb-2 px-4 flex justify-between items-center border-b border-crystal-800">
        <div className="flex items-center space-x-3">
          <div className="relative">
            <InfinityIcon className="text-crystal-glow animate-pulse-slow" size={24} />
          </div>
          <div>
            <h1 className="text-base font-bold tracking-widest font-mono text-white leading-none">
              CRYSTAL PRIME
            </h1>
            <p className="text-[9px] text-gray-500 font-mono tracking-wide mt-1">HUMAN ATTRACTION OS ∞</p>
          </div>
        </div>
        <button onClick={handleReset} className="text-gray-600 hover:text-red-400 p-2">
          <Trash2 size={16} />
        </button>
      </header>

      {/* TABS SCROLLBAR */}
      <div className="flex-none bg-[#080808] border-b border-crystal-800 overflow-x-auto no-scrollbar py-2 px-2 flex space-x-2">
        {TABS.map((tab) => {
          const isActive = activeTab === tab.id;
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-none flex items-center space-x-2 px-3 py-2 rounded-lg border transition-all duration-200 ${
                isActive 
                  ? `bg-crystal-800 border-crystal-600 ${tab.color}` 
                  : 'bg-transparent border-transparent text-gray-500 hover:text-gray-300'
              }`}
            >
              <Icon size={16} />
              <span className={`text-xs font-medium whitespace-nowrap font-mono ${isActive ? 'opacity-100' : 'opacity-70'}`}>
                {tab.label}
              </span>
            </button>
          );
        })}
      </div>

      {/* CHAT AREA */}
      <main ref={chatContainerRef} className="flex-1 overflow-y-auto p-4 space-y-6 scroll-smooth bg-[#050505]">
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center opacity-40 pointer-events-none p-8">
            <activeTabData.icon size={48} className={`mb-4 ${activeTabData.color} opacity-80`} />
            <h2 className={`text-lg font-mono font-bold mb-2 ${activeTabData.color}`}>{activeTabData.label}</h2>
            <p className="text-sm text-center text-gray-400 font-light max-w-xs">{activeTabData.desc}</p>
            <div className="mt-8 grid grid-cols-2 gap-8 text-center text-xs text-gray-600 font-mono">
              <div>
                <span className="block text-crystal-glow font-bold text-lg">{flirtLevel}</span>
