              <div>
                <span className="block text-crystal-glow font-bold text-lg">{wittyLevel}</span>
                NÍVEL LÁBIA
              </div>
            </div>
          </div>
        )}

        {messages.map((msg) => (
          <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-fade-in-up`}>
            {msg.role === 'user' && (
              <div className="max-w-[85%] text-right">
                 {msg.image && (
                  <div className="mb-2 rounded-lg overflow-hidden border border-crystal-700 shadow-lg inline-block">
                    <img src={msg.image} alt="Upload" className="max-h-48 object-cover opacity-80" />
                  </div>
                )}
                {msg.content && (
                  <div className="bg-crystal-800 border border-crystal-700 text-gray-300 px-3 py-2 rounded-xl rounded-tr-sm inline-block shadow-md">
                    <p className="text-xs font-mono">{msg.content}</p>
                  </div>
                )}
                {msg.mode && (
                  <div className="flex items-center justify-end space-x-2 mt-1 opacity-50">
                    <span className="text-[9px] font-mono text-gray-500 uppercase">{msg.mode.replace('_', ' ')}</span>
                    <span className="text-[9px] font-mono text-crystal-accent">F:{msg.flirtLevel} L:{msg.wittyLevel}</span>
                  </div>
                )}
              </div>
            )}

            {msg.role === 'assistant' && (
              <div className="w-full max-w-md">
                {msg.content ? (
                   <div className="bg-red-900/20 border border-red-900/50 text-red-200 px-4 py-3 rounded-lg text-sm">
                     {msg.content}
                   </div>
                ) : msg.analysis && (
                  <>
                    <AnalysisView analysis={msg.analysis} />
                    <ResponseOptions responses={msg.analysis.responses} />
                  </>
                )}
              </div>
            )}
          </div>
        ))}

        {status !== ProcessingState.IDLE && status !== ProcessingState.ERROR && (
           <div className="flex flex-col items-start space-y-2 animate-pulse pl-1">
             <div className="flex items-center space-x-2 text-crystal-accent">
               <div className="w-1.5 h-1.5 bg-current rounded-full animate-bounce"></div>
               <div className="w-1.5 h-1.5 bg-current rounded-full animate-bounce delay-100"></div>
               <div className="w-1.5 h-1.5 bg-current rounded-full animate-bounce delay-200"></div>
             </div>
           </div>
        )}
      </main>

      {/* CONTROLS & INPUT AREA */}
      <footer className="flex-none bg-[#0a0a0a] border-t border-crystal-800">

        {/* SLIDERS */}
        <div className="px-6 py-3 border-b border-crystal-800/50 bg-[#080808]">
          <div className="grid grid-cols-2 gap-6">
            <div className="space-y-1">
              <div className="flex justify-between items-center">
                <label className="text-[10px] font-mono text-gray-400 uppercase tracking-wider">Flirt <span className="text-crystal-glow">{flirtLevel}</span></label>
              </div>
              <input 
                type="range" min="0" max="10" step="1" 
                value={flirtLevel} 
                onChange={(e) => setFlirtLevel(parseInt(e.target.value))}
                className="w-full h-1 bg-crystal-700 rounded-lg appearance-none cursor-pointer accent-crystal-accent hover:accent-crystal-glow"
              />
            </div>
            <div className="space-y-1">
              <div className="flex justify-between items-center">
                <label className="text-[10px] font-mono text-gray-400 uppercase tracking-wider">Lábia <span className="text-crystal-glow">{wittyLevel}</span></label>
              </div>
              <input 
                type="range" min="0" max="10" step="1" 
                value={wittyLevel} 
                onChange={(e) => setWittyLevel(parseInt(e.target.value))}
                className="w-full h-1 bg-crystal-700 rounded-lg appearance-none cursor-pointer accent-crystal-accent hover:accent-crystal-glow"
              />
            </div>
          </div>
        </div>

        {/* INPUT */}
        <div className="p-3 max-w-4xl mx-auto">
          {selectedImage && (
            <div className="flex items-center bg-crystal-900 p-2 rounded-lg border border-crystal-700 w-fit mb-2">
              <img src={selectedImage} alt="Preview" className="h-8 w-8 object-cover rounded mr-2" />
