              <button onClick={handleClearImage} className="ml-2 text-gray-500 hover:text-white">
                <X size={14} />
              </button>
            </div>
          )}

          <form onSubmit={handleSubmit} className="flex items-center space-x-2">
            <input 
              type="file" 
              accept="image/*" 
              ref={fileInputRef}
              onChange={handleImageUpload}
              className="hidden" 
            />

            <button 
              type="button" 
              onClick={() => fileInputRef.current?.click()}
              className="p-3 rounded-xl bg-crystal-800 text-gray-400 hover:text-white transition-colors"
              disabled={status !== ProcessingState.IDLE}
            >
              <ImageIcon size={20} />
            </button>

            <div className="flex-1 relative">
              <input
                type="text"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                placeholder={activeTab === 'STORY_REPLY' ? "Cole o Story ou descreva..." : `Digite para modo ${activeTabData.label}...`}
                className="w-full bg-crystal-900/80 text-white placeholder-gray-600 rounded-xl py-3 px-4 border border-crystal-800 focus:border-crystal-glow focus:ring-1 focus:ring-crystal-glow focus:outline-none transition-all font-sans text-sm"
                disabled={status !== ProcessingState.IDLE}
              />
            </div>

            <button 
              type="submit" 
              className={`p-3 rounded-xl transition-all flex items-center justify-center ${
                (!inputText && !selectedImage) || status !== ProcessingState.IDLE
                  ? 'bg-crystal-800 text-gray-600' 
                  : 'bg-crystal-glow text-white shadow-lg shadow-crystal-glow/20'
              }`}
              disabled={(!inputText && !selectedImage) || status !== ProcessingState.IDLE}
            >
              {status === ProcessingState.IDLE ? <Send size={20} /> : <div className="w-5 h-5 border-2 border-white/30 border-t-white rounded-full animate-spin"></div>}
            </button>
          </form>
        </div>
      </footer>
    </div>
  );
};

