        </h3>
        <span className="text-[8px] text-gray-600 font-mono flex items-center">
          Deslize <ChevronRight size={10} />
        </span>
      </div>

      {/* Horizontal Scroll Container */}
      <div className="flex overflow-x-auto gap-4 pb-4 -mx-1 px-1 snap-x snap-mandatory">
        {responses.map((res, idx) => (
          <div 
            key={idx} 
            onClick={() => handleCopy(res.text, idx)}
            className={`flex-none w-[85%] sm:w-[300px] snap-center group relative bg-crystal-900 border transition-all duration-300 rounded-xl p-5 cursor-pointer flex flex-col justify-between
              ${copiedIndex === idx 
                ? 'border-green-500/50 shadow-[0_0_20px_rgba(16,185,129,0.1)]' 
                : 'border-crystal-800 hover:border-crystal-gold/40 hover:bg-[#0c0c0c] hover:shadow-[0_0_20px_rgba(212,175,55,0.05)]'}
            `}
          >
            <div>
              <div className="flex justify-between items-start mb-3">
                <span className="text-[9px] font-mono text-gray-500 uppercase tracking-wider border border-gray-800 px-2 py-0.5 rounded-full">{res.type}</span>
                <div className="text-gray-600 group-hover:text-crystal-gold transition-colors">
                  {copiedIndex === idx ? <Check size={14} className="text-green-500" /> : <Copy size={14} />}
                </div>
              </div>
              <p className="text-gray-200 font-medium text-sm leading-relaxed select-none whitespace-pre-wrap">{res.text}</p>
            </div>

            <div className="mt-4 pt-3 border-t border-gray-900/50 flex justify-end">
              <span className="text-[8px] text-gray-700 font-mono uppercase">
                {copiedIndex === idx ? 'Copiado!' : 'Toque para copiar'}
              </span>
            </div>

            {copiedIndex === idx && (
              <div className="absolute inset-0 rounded-xl border border-green-500/20 animate-pulse pointer-events-none"></div>
            )}
          </div>
        ))}
        {/* Spacer for right padding in scroll */}
        <div className="w-2 flex-none"></div>
      </div>
    </div>
  );
};

export default ResponseOptions;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeContent } from './services/gemini';
import { Message, ProcessingState, CrystalMode, ConversationSpeed } from './types';
import AnalysisView from './components/AnalysisView';
import ResponseOptions from './components/ResponseOptions';
import { Send, ImageIcon, X, Trash2, Infinity as InfinityIcon, Camera, MessageCircle, Zap, ShieldAlert, ThermometerSnowflake, Ghost, Repeat2, Bolt, User, Crown, Feather, Gauge } from 'lucide-react';

// --- CONSTANTS ---

const TABS: { id: CrystalMode; label: string; icon: React.FC<any>; desc: string }[] = [
  { id: 'STORY_REPLY', label: 'Story', icon: Camera, desc: 'Reação a Stories' },
  { id: 'FIRST_CONTACT', label: 'Abrir', icon: MessageCircle, desc: 'Primeiro Contato' },
  { id: 'FLOWING', label: 'Flow', icon: Zap, desc: 'Manter Conversa' },
  { id: 'VALUE_TEST', label: 'Teste', icon: ShieldAlert, desc: 'Teste de Valor' },
  { id: 'COLD_RESPONSE', label: 'Fria', icon: ThermometerSnowflake, desc: 'Recuperar Poder' },
  { id: 'SILENCE', label: 'Vácuo', icon: Ghost, desc: 'Estratégia de Silêncio' },
  { id: 'REACTIVATION', label: 'Reviver', icon: Repeat2, desc: 'Reativação' },
  { id: 'ONE_LINER', label: '1 Linha', icon: Bolt, desc: 'Impacto Extremo' },
];

const PROFILES = [
  { id: 'CALM', label: 'Calmo', dominance: 5, mystery: 4, flirt: 3, witty: 4, speed: 'normal' as ConversationSpeed, icon: Feather },
  { id: 'IRONIC', label: 'Irônico', dominance: 6, mystery: 5, flirt: 6, witty: 8, speed: 'fluid' as ConversationSpeed, icon: Zap },
  { id: 'DOMINANT', label: 'Líder', dominance: 9, mystery: 6, flirt: 7, witty: 6, speed: 'short' as ConversationSpeed, icon: Crown },
  { id: 'BOLD', label: 'Ousado', dominance: 7, mystery: 8, flirt: 9, witty: 7, speed: 'normal' as ConversationSpeed, icon: Bolt },
];

const App: React.FC = () => {
  const [messages, setMessages] = useState<Message[]>([]);
  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);

  // State
  const [activeTab, setActiveTab] = useState<CrystalMode>('STORY_REPLY');
  const [activeProfile, setActiveProfile] = useState<string>('CALM');

  // Sliders
  const [flirtLevel, setFlirtLevel] = useState<number>(3);
  const [wittyLevel, setWittyLevel] = useState<number>(4);
  const [dominanceLevel, setDominanceLevel] = useState<number>(5);
  const [mysteryLevel, setMysteryLevel] = useState<number>(4);
  const [speed, setSpeed] = useState<ConversationSpeed>('normal');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  const activeTabData = TABS.find(t => t.id === activeTab)!;

  // Auto-set sliders when profile changes
  const handleProfileChange = (profileId: string) => {
    const p = PROFILES.find(pr => pr.id === profileId);
    if (p) {
      setActiveProfile(profileId);
      setFlirtLevel(p.flirt);
      setWittyLevel(p.witty);
      setDominanceLevel(p.dominance);
      setMysteryLevel(p.mystery);
      setSpeed(p.speed);
    }
  };

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [messages, status]);

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleReset = () => {
    setMessages([]);
    setInputText('');
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    setStatus(ProcessingState.IDLE);
    handleProfileChange('CALM');
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if ((!inputText.trim() && !selectedImage) || status !== ProcessingState.IDLE) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      image: selectedImage || undefined,
      timestamp: Date.now(),
      mode: activeTab,
      flirtLevel,
      wittyLevel,
      dominanceLevel,
      mysteryLevel,
      speed
    };

    setMessages(prev => [...prev, newMessage]);
    setInputText('');
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    setStatus(ProcessingState.ANALYZING);

    try {
      const analysis = await analyzeContent(
        newMessage.content || '', 
        newMessage.image,
        activeTab,
        flirtLevel,
        wittyLevel,
        dominanceLevel,
        mysteryLevel,
        speed
      );

      const responseMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        analysis: analysis,
        timestamp: Date.now(),
      };

      setMessages(prev => [...prev, responseMessage]);
      setStatus(ProcessingState.IDLE);
    } catch (error) {
      console.error(error);
      setStatus(ProcessingState.ERROR);
      setMessages(prev => [...prev, {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "Sistema desconectado. Verifique sua conexão.",
        timestamp: Date.now(),
      }]);
      setTimeout(() => setStatus(ProcessingState.IDLE), 3000);
    }
  };

  return (
    <div className="flex flex-col h-screen bg-[#000000] text-gray-200 font-sans overflow-hidden">

      {/* HEADER */}
      <header className="flex-none bg-[#050505] z-20 pt-4 pb-2 px-4 flex justify-between items-center border-b border-crystal-800">
        <div className="flex items-center space-x-3">
          <InfinityIcon className="text-crystal-gold" size={20} />
          <div>
            <h1 className="text-sm font-bold tracking-[0.2em] font-mono text-white leading-none">
              CRYSTAL PRIME
            </h1>
            <p className="text-[8px] text-crystal-gold/70 font-mono tracking-widest mt-0.5">AMORIM INC • PREMIUM OS</p>
          </div>
        </div>
        <button onClick={handleReset} className="text-gray-700 hover:text-red-900 transition-colors p-2">
          <Trash2 size={16} />
        </button>
      </header>

      {/* TABS SCROLLBAR */}
      {/* Removed no-scrollbar to ensure scrollability is visible and accessible */}
      <div className="flex-none bg-[#050505] border-b border-crystal-800 overflow-x-auto py-3 px-2 flex space-x-2 z-10">
        {TABS.map((tab) => {
          const isActive = activeTab === tab.id;
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-none flex items-center space-x-2 px-3 py-2 rounded-full border transition-all duration-300 ${
                isActive 
                  ? 'bg-crystal-gold/10 border-crystal-gold text-crystal-gold shadow-[0_0_10px_rgba(212,175,55,0.1)]' 
                  : 'bg-[#0a0a0a] border-crystal-800 text-gray-500 hover:text-gray-300'
              }`}
            >
              <Icon size={14} />
              <span className="text-[10px] font-bold uppercase tracking-wider font-mono">
                {tab.label}
              </span>
            </button>
          );
        })}
      </div>

      {/* CHAT AREA */}
      <main ref={chatContainerRef} className="flex-1 overflow-y-auto p-4 space-y-8 scroll-smooth bg-[#000000]">
        {messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center opacity-30 pointer-events-none p-8">
            <activeTabData.icon size={48} className="mb-6 text-gray-800" />
            <div className="text-center space-y-2">
              <h2 className="text-base font-mono font-bold text-gray-600 tracking-[0.2em]">{activeTabData.desc.toUpperCase()}</h2>
              <p className="text-xs text-gray-700 font-light">Aguardando Input...</p>
            </div>

            <div className="mt-12 text-[10px] font-mono text-gray-800 tracking-widest uppercase">
              Amorim Inc • Inteligência Social
            </div>
          </div>
        )}

        {messages.map((msg) => (
          <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} animate-fade-in`}>
            {msg.role === 'user' && (
              <div className="max-w-[85%] text-right">
                 {msg.image && (
                  <div className="mb-2 rounded border border-crystal-800 inline-block overflow-hidden">
                    <img src={msg.image} alt="Upload" className="max-h-48 object-cover opacity-90" />
                  </div>
                )}
                {msg.content && (
                  <div className="bg-[#121212] border border-crystal-800 text-gray-300 px-4 py-2 rounded-2xl rounded-tr-sm inline-block">
                    <p className="text-xs font-mono">{msg.content}</p>
                  </div>
                )}
                {msg.mode && (
                  <div className="flex items-center justify-end space-x-2 mt-1 opacity-40">
                    <span className="text-[8px] font-mono text-gray-600 uppercase tracking-wider">{msg.speed}</span>
                  </div>
                )}
              </div>
            )}

            {msg.role === 'assistant' && (
              <div className="w-full">
                {msg.content ? (
                   <div className="bg-red-950/20 border border-red-900/30 text-red-400 px-4 py-3 rounded-lg text-xs font-mono max-w-md">
                     {msg.content}
                   </div>
                ) : msg.analysis && (
                  <>
                    <div className="max-w-md">
                      <AnalysisView analysis={msg.analysis} />
                    </div>
                    {/* Full width for horizontal scroll */}
                    <div className="-mx-2">
                      <ResponseOptions responses={msg.analysis.responses} />
                    </div>
                  </>
                )}
              </div>
            )}
          </div>
        ))}

        {status !== ProcessingState.IDLE && status !== ProcessingState.ERROR && (
           <div className="flex items-center space-x-2 pl-2 opacity-50">
             <div className="w-1 h-1 bg-crystal-gold rounded-full animate-bounce"></div>
             <div className="w-1 h-1 bg-crystal-gold rounded-full animate-bounce delay-100"></div>
             <div className="w-1 h-1 bg-crystal-gold rounded-full animate-bounce delay-200"></div>
           </div>
        )}
      </main>

      {/* CONTROLS & INPUT AREA */}
      <footer className="flex-none bg-[#050505] border-t border-crystal-800 shadow-[0_-10px_40px_rgba(0,0,0,0.8)] z-20">

        {/* PROFILES & SLIDERS */}
        <div className="px-5 py-4 border-b border-crystal-800/50">

          {/* Profiles */}
          {/* Removed no-scrollbar to ensure scrollability is visible */}
          <div className="flex space-x-3 mb-4 overflow-x-auto pb-2">
             {PROFILES.map(p => {
               const Icon = p.icon;
               const isActive = activeProfile === p.id;
               return (
                 <button
                    key={p.id}
                    onClick={() => handleProfileChange(p.id)}
                    className={`flex-none flex items-center space-x-1.5 px-3 py-1.5 rounded-full border text-[10px] font-mono uppercase tracking-wide transition-all ${
                      isActive 
                      ? 'bg-crystal-gold/20 border-crystal-gold text-crystal-gold' 
                      : 'bg-transparent border-crystal-800 text-gray-600 hover:border-gray-600'
                    }`}
                 >
                   <Icon size={10} />
                   <span>{p.label}</span>
                 </button>
               )
             })}
          </div>

          {/* New Grid Layout for Advanced Sliders */}
          <div className="grid grid-cols-2 gap-x-6 gap-y-3">
            {/* Flirt */}
            <div className="space-y-1">
              <div className="flex justify-between text-[8px] font-mono text-gray-500 uppercase">
                <span>Flirt</span>
                <span className="text-crystal-gold">{flirtLevel}</span>
              </div>
              <input type="range" min="0" max="10" value={flirtLevel} onChange={(e) => setFlirtLevel(parseInt(e.target.value))} className="w-full h-1 bg-crystal-800 rounded-lg appearance-none cursor-pointer accent-crystal-gold" />
            </div>

            {/* Dominance */}
            <div className="space-y-1">
              <div className="flex justify-between text-[8px] font-mono text-gray-500 uppercase">
                <span>Dominância</span>
                <span className="text-crystal-gold">{dominanceLevel}</span>
              </div>
              <input type="range" min="0" max="10" value={dominanceLevel} onChange={(e) => setDominanceLevel(parseInt(e.target.value))} className="w-full h-1 bg-crystal-800 rounded-lg appearance-none cursor-pointer accent-crystal-gold" />
            </div>

             {/* Mystery */}
             <div className="space-y-1">
              <div className="flex justify-between text-[8px] font-mono text-gray-500 uppercase">
                <span>Mistério</span>
                <span className="text-crystal-gold">{mysteryLevel}</span>
              </div>
              <input type="range" min="0" max="10" value={mysteryLevel} onChange={(e) => setMysteryLevel(parseInt(e.target.value))} className="w-full h-1 bg-crystal-800 rounded-lg appearance-none cursor-pointer accent-crystal-gold" />
            </div>

            {/* Speed Toggle */}
            <div className="flex items-end h-full pb-1">
               <button 
                 onClick={() => setSpeed(s => s === 'short' ? 'normal' : s === 'normal' ? 'fluid' : 'short')}
                 className="w-full flex justify-between items-center bg-crystal-800/50 px-2 py-1 rounded border border-crystal-800 hover:border-crystal-600 text-[9px] font-mono text-gray-400 uppercase"
               >
                 <span>Velocidade</span>
                 <span className="text-crystal-gold">{speed === 'short' ? 'Curta' : speed === 'normal' ? 'Normal' : 'Fluida'}</span>
               </button>
            </div>
          </div>
        </div>

        {/* INPUT */}
        <div className="p-3 max-w-4xl mx-auto">
          {selectedImage && (
            <div className="flex items-center bg-[#121212] p-2 rounded border border-crystal-800 w-fit mb-2">
              <img src={selectedImage} alt="Preview" className="h-8 w-8 object-cover rounded mr-2 opacity-80" />
              <button onClick={() => {setSelectedImage(null); if(fileInputRef.current) fileInputRef.current.value=''}} className="text-gray-600 hover:text-white">
                <X size={14} />
              </button>
            </div>
          )}

          <form onSubmit={handleSubmit} className="flex items-center space-x-2">
            <input 
              type="file" 
              accept="image/*" 
              ref={fileInputRef}
              onChange={handleImageUpload}
              className="hidden" 
            />

            <button 
              type="button" 
              onClick={() => fileInputRef.current?.click()}
              className="p-3 rounded-xl bg-[#0a0a0a] border border-crystal-800 text-gray-500 hover:text-crystal-gold hover:border-crystal-gold/50 transition-all"
              disabled={status !== ProcessingState.IDLE}
            >
              <ImageIcon size={18} />
            </button>

            <div className="flex-1 relative">
              <input
                type="text"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                placeholder={activeTab === 'STORY_REPLY' ? "Anexar Story ou descrever..." : `Comando para modo ${activeTabData.label}...`}
                className="w-full bg-[#0a0a0a] text-gray-200 placeholder-gray-700 rounded-xl py-3 px-4 border border-crystal-800 focus:border-crystal-gold/50 focus:ring-1 focus:ring-crystal-gold/30 focus:outline-none transition-all font-sans text-sm"
                disabled={status !== ProcessingState.IDLE}
              />
            </div>

            <button 
              type="submit" 
              className={`p-3 rounded-xl transition-all flex items-center justify-center border ${
                (!inputText && !selectedImage) || status !== ProcessingState.IDLE
                  ? 'bg-[#0a0a0a] border-crystal-800 text-gray-700' 
                  : 'bg-crystal-gold text-black border-crystal-gold hover:bg-yellow-500 shadow-[0_0_15px_rgba(212,175,55,0.2)]'
              }`}
              disabled={(!inputText && !selectedImage) || status !== ProcessingState.IDLE}
            >
              {status === ProcessingState.IDLE ? <Send size={18} /> : <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin"></div>}
            </button>
          </form>

          <div className="flex justify-between items-center mt-2 px-2">
            <span className="text-[8px] text-gray-800 font-mono tracking-widest uppercase">
              Amorim Inc v2.0 • Premium
            </span>
             <span className="text-[8px] text-crystal-gold/50 font-mono tracking-widest uppercase animate-pulse">
              ● Online
            </span>
          </div>
        </div>
      </footer>
    </div>
  );
};

export default App;

export interface Message {
  id: string;
  role: 'user' | 'assistant';
  content?: string;
  image?: string; // base64
  analysis?: CrystalAnalysis;
  timestamp: number;
  // Context history
  mode?: string;
  flirtLevel?: number;
  wittyLevel?: number;
  dominanceLevel?: number;
  mysteryLevel?: number;
  speed?: 'short' | 'normal' | 'fluid';
}

export interface CrystalAnalysis {
  momentReading: string;
  interestLevel: 'Baixo' | 'Médio' | 'Alto' | 'Oscilante';
  emotion: string;
  dynamic: string;
  risk: string;
  responses: Array<{
    type: string;
    text: string;
  }>;
  rhythm: 'Agora' | 'Esperar' | 'Mudar assunto' | 'Sumir' | 'Encerrar';
  detectedMode: string;
}

export enum ProcessingState {
  IDLE = 'IDLE',
  ANALYZING = 'ANALYZING',
  CALCULATING = 'CALCULATING',
  ERROR = 'ERROR'
}

export type CrystalMode = 
  | 'STORY_REPLY' 
  | 'FIRST_CONTACT' 
  | 'FLOWING' 
  | 'VALUE_TEST' 
  | 'COLD_RESPONSE' 
  | 'SILENCE' 
  | 'REACTIVATION' 
  | 'ONE_LINER';

export type ConversationSpeed = 'short' | 'normal' | 'fluid';

export interface AppSettings {
  theme: 'dark' | 'ultra-dark';
  accentColor: 'gold' | 'red' | 'blue';
  animations: boolean;
  ai: {
    shortResponses: boolean;
    avoidCompliments: boolean;
    avoidQuestions: boolean;
    autoAdjustFlirt: boolean;
  };
  safety: {
    antiNeedy: boolean;
    antiLongText: boolean;
    antiRobot: boolean;
    antiOverflirt: boolean;
  };
}

