import { GoogleGenAI, Type, Schema } from "@google/genai";
import { SYSTEM_PROMPT, CrystalAnalysis, CrystalMode, ConversationSpeed, AppSettings } from "../types";

const apiKey = process.env.API_KEY || '';

const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    momentReading: { type: Type.STRING },
    interestLevel: { type: Type.STRING, enum: ["Baixo", "Médio", "Alto", "Oscilante"] },
    emotion: { type: Type.STRING },
    dynamic: { type: Type.STRING },
    risk: { type: Type.STRING },
    detectedMode: { type: Type.STRING },
    responses: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          type: { type: Type.STRING },
          text: { type: Type.STRING }
        },
        required: ["type", "text"]
      }
    },
    rhythm: { type: Type.STRING, enum: ["Agora", "Esperar", "Mudar assunto", "Sumir", "Encerrar"] }
  },
  required: ["momentReading", "interestLevel", "emotion", "dynamic", "risk", "detectedMode", "responses", "rhythm"]
};

export const analyzeContent = async (
  text: string, 
  imageBase64: string | undefined,
  mode: CrystalMode,
  flirtLevel: number,
  wittyLevel: number,
  dominanceLevel: number,
  mysteryLevel: number,
  speed: ConversationSpeed,
  settings: AppSettings
): Promise<CrystalAnalysis> => {
  if (!apiKey) {
    throw new Error("API Key not found in environment.");
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = "gemini-3-pro-preview"; 

  const parts: any[] = [];

  const contextInstruction = `
  ⚡ AMORIM INC - PARÂMETROS DE OPERAÇÃO:

  MODO: ${mode}

  🎚️ SLIDERS (Intenção do Usuário):
  - Flirt: ${flirtLevel}/10
  - Lábia: ${wittyLevel}/10
  - Dominância: ${dominanceLevel}/10
  - Mistério: ${mysteryLevel}/10

  ⚡ VELOCIDADE: ${speed.toUpperCase()}

  ⚙️ CONFIGURAÇÕES GLOBAIS (RESPEITE RIGOROSAMENTE):
  - Respostas Curtas: ${settings.ai.shortResponses ? 'ATIVADO (Seja breve)' : 'OFF'}
  - Zero Elogios Físicos: ${settings.ai.avoidCompliments ? 'ATIVADO (Proibido chamar de linda/gata)' : 'OFF'}
  - Evitar Perguntas: ${settings.ai.avoidQuestions ? 'ATIVADO (Prefira afirmações)' : 'OFF'}
  - Auto-Ajuste de Risco: ${settings.ai.autoAdjustFlirt ? 'ATIVADO (Reduza flirt se houver risco)' : 'OFF'}
  - Anti-Carência: ${settings.safety.antiNeedy ? 'ATIVADO' : 'OFF'}

  ⚠️ ATENÇÃO: Se a leitura de risco for alta, ignore os sliders altos e proteja o valor do usuário (Auto-Correção).
  `;

  parts.push({ text: contextInstruction });

  if (imageBase64) {
    const cleanBase64 = imageBase64.split(',')[1] || imageBase64;
    parts.push({
      inlineData: {
        mimeType: "image/jpeg",
        data: cleanBase64
      }
    });
  }

  if (text) {
    parts.push({ text });
  }

  if (parts.length === 1) {
    throw new Error("No content to analyze.");
  }

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: parts
      },
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.75, 
      }
    });

    const responseText = response.text;
    if (!responseText) throw new Error("Empty response from Crystal Prime.");

    const analysis = JSON.parse(responseText) as CrystalAnalysis;
    return analysis;

  } catch (error) {
    console.error("Crystal Prime Error:", error);
    throw error;
  }
};

