              <input type="range" min="0" max="10" value={dominanceLevel} onChange={(e) => setDominanceLevel(parseInt(e.target.value))} className="w-full h-1 bg-crystal-800 rounded-lg appearance-none cursor-pointer" />
            </div>

             {/* Mystery */}
             <div className="space-y-1">
              <div className="flex justify-between text-[8px] font-mono text-gray-500 uppercase">
                <span>Mistério</span>
                <span className={getAccentText()}>{mysteryLevel}</span>
              </div>
              <input type="range" min="0" max="10" value={mysteryLevel} onChange={(e) => setMysteryLevel(parseInt(e.target.value))} className="w-full h-1 bg-crystal-800 rounded-lg appearance-none cursor-pointer" />
            </div>

            {/* Speed Toggle */}
            <div className="flex items-end h-full pb-1">
               <button 
                 onClick={() => setSpeed(s => s === 'short' ? 'normal' : s === 'normal' ? 'fluid' : 'short')}
                 className="w-full flex justify-between items-center bg-crystal-800/50 px-2 py-1 rounded border border-crystal-800 hover:border-crystal-600 text-[9px] font-mono text-gray-400 uppercase"
               >
                 <span>Velocidade</span>
                 <span className={getAccentText()}>{speed === 'short' ? 'Curta' : speed === 'normal' ? 'Normal' : 'Fluida'}</span>
               </button>
            </div>
          </div>
        </div>

        {/* INPUT */}
        <div className="p-3 max-w-4xl mx-auto">
          {selectedImage && (
            <div className="flex items-center bg-[#121212] p-2 rounded border border-crystal-800 w-fit mb-2">
              <img src={selectedImage} alt="Preview" className="h-8 w-8 object-cover rounded mr-2 opacity-80" />
              <button onClick={() => {setSelectedImage(null); if(fileInputRef.current) fileInputRef.current.value=''}} className="text-gray-600 hover:text-white">
                <X size={14} />
              </button>
            </div>
          )}

          <form onSubmit={handleSubmit} className="flex items-center space-x-2">
            <input 
              type="file" 
              accept="image/*" 
              ref={fileInputRef}
              onChange={handleImageUpload}
              className="hidden" 
            />

            <button 
              type="button" 
              onClick={() => fileInputRef.current?.click()}
              className={`p-3 rounded-xl bg-[#0a0a0a] border border-crystal-800 text-gray-500 transition-all hover:text-white`}
              disabled={status !== ProcessingState.IDLE}
            >
              <ImageIcon size={18} />
            </button>

            <div className="flex-1 relative">
              <input
                type="text"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                placeholder={activeTab === 'STORY_REPLY' ? "Anexar Story ou descrever..." : `Comando para modo ${activeTabData.label}...`}
                className="w-full bg-[#0a0a0a] text-gray-200 placeholder-gray-700 rounded-xl py-3 px-4 border border-crystal-800 focus:border-white/20 focus:ring-1 focus:ring-white/10 focus:outline-none transition-all font-sans text-sm"
                disabled={status !== ProcessingState.IDLE}
              />
            </div>

            <button 
              type="submit" 
              className={`p-3 rounded-xl transition-all flex items-center justify-center border ${
                (!inputText && !selectedImage) || status !== ProcessingState.IDLE
                  ? 'bg-[#0a0a0a] border-crystal-800 text-gray-700' 
                  : `${getAccentBg()} text-black border-transparent hover:opacity-90 shadow-lg`
              }`}
              disabled={(!inputText && !selectedImage) || status !== ProcessingState.IDLE}
            >
              {status === ProcessingState.IDLE ? <Send size={18} /> : <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin"></div>}
            </button>
          </form>

          <div className="flex justify-between items-center mt-2 px-2">
            <span className="text-[8px] text-gray-800 font-mono tracking-widest uppercase">
              Amorim Inc v2.4 • Premium
            </span>
             <span className={`text-[8px] font-mono tracking-widest uppercase animate-pulse ${getAccentText()} opacity-50`}>
              ● Online
            </span>
          </div>
        </div>
      </footer>
    </div>
  );
};

