import { GoogleGenAI, Type, Schema } from "@google/genai";
import { SYSTEM_PROMPT, LAB_PROMPT, CrystalAnalysis, CrystalMode, ConversationSpeed, AppSettings, LaboratorySimulation, Profile } from "../types";

const apiKey = process.env.API_KEY || '';

const responseSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    momentReading: { type: Type.STRING },
    interestLevel: { type: Type.STRING, enum: ["Baixo", "Médio", "Alto", "Oscilante"] },
    emotion: { type: Type.STRING },
    dynamic: { type: Type.STRING },
    risk: { type: Type.STRING },
    detectedMode: { type: Type.STRING },
    responses: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          type: { type: Type.STRING },
          text: { type: Type.STRING }
        },
        required: ["type", "text"]
      }
    },
    rhythm: { type: Type.STRING, enum: ["Agora", "Esperar", "Mudar assunto", "Sumir", "Encerrar"] }
  },
  required: ["momentReading", "interestLevel", "emotion", "dynamic", "risk", "detectedMode", "responses", "rhythm"]
};

const labSchema: Schema = {
  type: Type.OBJECT,
  properties: {
    variations: {
      type: Type.ARRAY,
      items: {
        type: Type.OBJECT,
        properties: {
          style: { type: Type.STRING, enum: ["Confiante", "Provocante", "Misteriosa"] },
          text: { type: Type.STRING },
          impact: {
            type: Type.OBJECT,
            properties: {
              attraction: { type: Type.STRING, enum: ["Baixa", "Média", "Alta"] },
              curiosity: { type: Type.STRING, enum: ["Baixa", "Média", "Alta"] },
              risk: { type: Type.STRING, enum: ["Baixo", "Médio", "Alto"] }
            },
            required: ["attraction", "curiosity", "risk"]
          },
          bestScenario: { type: Type.STRING }
        },
        required: ["style", "text", "impact", "bestScenario"]
      }
    },
    prediction: {
      type: Type.OBJECT,
      properties: {
        likelyResponse: { type: Type.STRING },
        alternativeResponse: { type: Type.STRING },
        adviceIfSilence: { type: Type.STRING },
        adviceIfResponse: { type: Type.STRING }
      },
      required: ["likelyResponse", "alternativeResponse", "adviceIfSilence", "adviceIfResponse"]
    }
  },
  required: ["variations", "prediction"]
};

export const analyzeContent = async (
  text: string, 
  imageBase64: string | undefined,
  mode: CrystalMode,
  flirtLevel: number,
  wittyLevel: number,
  dominanceLevel: number,
  mysteryLevel: number,
  speed: ConversationSpeed,
  settings: AppSettings,
  profileContext?: Profile // Optional specific profile data
): Promise<CrystalAnalysis> => {
  if (!apiKey) {
    throw new Error("API Key not found in environment.");
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = "gemini-3-pro-preview"; 

  const parts: any[] = [];

  let profileInstruction = "";
  if (profileContext && profileContext.name !== "Geral") {
    profileInstruction = `
    👤 PERFIL ATIVO: ${profileContext.name} (${profileContext.description})
    HISTÓRICO: O usuário já trocou ${profileContext.messages.length} mensagens.
    PADRÃO DELA: ${profileContext.behavioralPattern || "Ainda em análise"}
    RISCO ANTERIOR: ${profileContext.metrics.risk}
    `;
  }

  const contextInstruction = `
  ⚡ AMORIM INC - PARÂMETROS DE OPERAÇÃO:

  MODO: ${mode}
  ${profileInstruction}

  🎚️ SLIDERS (Intenção do Usuário):
  - Flirt: ${flirtLevel}/10
  - Lábia: ${wittyLevel}/10
  - Dominância: ${dominanceLevel}/10
  - Mistério: ${mysteryLevel}/10

  ⚡ VELOCIDADE: ${speed.toUpperCase()}

  ⚙️ CONFIGURAÇÕES GLOBAIS (RESPEITE RIGOROSAMENTE):
  - Respostas Curtas: ${settings.ai.shortResponses ? 'ATIVADO (Seja breve)' : 'OFF'}
  - Zero Elogios Físicos: ${settings.ai.avoidCompliments ? 'ATIVADO (Proibido chamar de linda/gata)' : 'OFF'}
  - Evitar Perguntas: ${settings.ai.avoidQuestions ? 'ATIVADO (Prefira afirmações)' : 'OFF'}
  - Auto-Ajuste de Risco: ${settings.ai.autoAdjustFlirt ? 'ATIVADO (Reduza flirt se houver risco)' : 'OFF'}
  - Anti-Carência: ${settings.safety.antiNeedy ? 'ATIVADO' : 'OFF'}

  ⚠️ ATENÇÃO: Se a leitura de risco for alta, ignore os sliders altos e proteja o valor do usuário (Auto-Correção).
  `;

  parts.push({ text: contextInstruction });

  if (imageBase64) {
    const cleanBase64 = imageBase64.split(',')[1] || imageBase64;
    parts.push({
      inlineData: {
        mimeType: "image/jpeg",
        data: cleanBase64
      }
    });
  }

  if (text) {
    parts.push({ text });
  }

  if (parts.length === 1) {
    throw new Error("No content to analyze.");
  }

  try {
    const response = await ai.models.generateContent({
      model,
      contents: {
        parts: parts
      },
      config: {
        systemInstruction: SYSTEM_PROMPT,
        responseMimeType: "application/json",
        responseSchema: responseSchema,
        temperature: 0.75, 
      }
    });

    const responseText = response.text;
    if (!responseText) throw new Error("Empty response from Crystal Prime.");

    const analysis = JSON.parse(responseText) as CrystalAnalysis;
    return analysis;

  } catch (error) {
    console.error("Crystal Prime Error:", error);
    throw error;
  }
};

export const runLaboratory = async (
  contextText: string,
  analysis: CrystalAnalysis,
  profileContext?: Profile
): Promise<LaboratorySimulation> => {
   if (!apiKey) {
    throw new Error("API Key not found in environment.");
  }

  const ai = new GoogleGenAI({ apiKey });
  const model = "gemini-3-pro-preview"; 

  const parts: any[] = [];

  let profileInfo = "";
  if (profileContext) {
    profileInfo = `Perfil: ${profileContext.name}. Nível de Interesse: ${profileContext.metrics.interest}.`;
  }

  parts.push({ 
    text: `INPUT ORIGINAL: "${contextText}"
    ANÁLISE INICIAL: ${JSON.stringify(analysis)}
    CONTEXTO DE PERFIL: ${profileInfo}

    Execute a simulação do laboratório agora.` 
  });

  try {
    const response = await ai.models.generateContent({
      model,
      contents: { parts },
      config: {
        systemInstruction: SYSTEM_PROMPT + "\n" + LAB_PROMPT,
        responseMimeType: "application/json",
        responseSchema: labSchema,
        temperature: 0.8
      }
    });

    if(!response.text) throw new Error("Failed to generate lab results");
    return JSON.parse(response.text) as LaboratorySimulation;

  } catch (e) {
    console.error("Lab Error", e);
    throw e;
  }
}

