      <div className="bg-[#0a0a0a] border border-crystal-gold/20 rounded-xl w-full max-w-sm relative overflow-hidden">
        <div className="absolute top-0 left-0 w-full h-1 bg-gradient-to-r from-transparent via-crystal-gold to-transparent opacity-50"></div>

