};

export default HelpModal;

import React, { useState, useRef, useEffect } from 'react';
import { analyzeContent, runLaboratory } from './services/gemini';
import { Message, ProcessingState, CrystalMode, ConversationSpeed, AppSettings, Profile } from './types';
import AnalysisView from './components/AnalysisView';
import ResponseOptions from './components/ResponseOptions';
import SettingsView from './components/SettingsView';
import ProfilesView from './components/ProfilesView';
import LaboratoryView from './components/LaboratoryView';
import HelpModal from './components/HelpModal';
import { Send, ImageIcon, X, Trash2, Infinity as InfinityIcon, Camera, MessageCircle, Zap, ShieldAlert, ThermometerSnowflake, Ghost, Repeat2, Bolt, User, Crown, Feather, Settings, Users, HelpCircle, FlaskConical } from 'lucide-react';

// --- CONSTANTS ---

const TABS: { id: CrystalMode; label: string; icon: React.FC<any>; desc: string }[] = [
  { id: 'STORY_REPLY', label: 'Story', icon: Camera, desc: 'Reação a Stories' },
  { id: 'FIRST_CONTACT', label: 'Abrir', icon: MessageCircle, desc: 'Primeiro Contato' },
  { id: 'FLOWING', label: 'Flow', icon: Zap, desc: 'Manter Conversa' },
  { id: 'VALUE_TEST', label: 'Teste', icon: ShieldAlert, desc: 'Teste de Valor' },
  { id: 'COLD_RESPONSE', label: 'Fria', icon: ThermometerSnowflake, desc: 'Recuperar Poder' },
  { id: 'SILENCE', label: 'Vácuo', icon: Ghost, desc: 'Estratégia de Silêncio' },
  { id: 'REACTIVATION', label: 'Reviver', icon: Repeat2, desc: 'Reativação' },
  { id: 'ONE_LINER', label: '1 Linha', icon: Bolt, desc: 'Impacto Extremo' },
];

const PROFILES_STYLES = [
  { id: 'CALM', label: 'Calmo', dominance: 5, mystery: 4, flirt: 3, witty: 4, speed: 'normal' as ConversationSpeed, icon: Feather },
  { id: 'IRONIC', label: 'Irônico', dominance: 6, mystery: 5, flirt: 6, witty: 8, speed: 'fluid' as ConversationSpeed, icon: Zap },
  { id: 'DOMINANT', label: 'Líder', dominance: 9, mystery: 6, flirt: 7, witty: 6, speed: 'short' as ConversationSpeed, icon: Crown },
  { id: 'BOLD', label: 'Ousado', dominance: 7, mystery: 8, flirt: 9, witty: 7, speed: 'normal' as ConversationSpeed, icon: Bolt },
];

const DEFAULT_SETTINGS: AppSettings = {
  theme: 'dark',
  accentColor: 'gold',
  animations: true,
  ai: {
    shortResponses: false,
    avoidCompliments: true,
    avoidQuestions: false,
    autoAdjustFlirt: true
  },
  safety: {
    antiNeedy: true,
    antiLongText: true,
    antiRobot: true,
    antiOverflirt: true
  }
};

const App: React.FC = () => {
  // Global State
  const [profiles, setProfiles] = useState<Profile[]>([
    { id: 'general', name: 'Geral', description: 'Modo Anônimo', messages: [], metrics: { interest: 'Oscilante', risk: 'Baixo', lastInteraction: Date.now() }, behavioralPattern: '' }
  ]);
  const [activeProfileId, setActiveProfileId] = useState<string>('general');
  const activeProfile = profiles.find(p => p.id === activeProfileId) || profiles[0];

  const [inputText, setInputText] = useState('');
  const [selectedImage, setSelectedImage] = useState<string | null>(null);
  const [status, setStatus] = useState<ProcessingState>(ProcessingState.IDLE);

  // View States
  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isProfilesOpen, setIsProfilesOpen] = useState(false);
  const [helpMode, setHelpMode] = useState<CrystalMode | null>(null);

  const [settings, setSettings] = useState<AppSettings>(DEFAULT_SETTINGS);

  // Tab & Sliders State
  const [activeTab, setActiveTab] = useState<CrystalMode>('STORY_REPLY');
  const [activeProfileStyle, setActiveProfileStyle] = useState<string>('CALM');
  const [flirtLevel, setFlirtLevel] = useState<number>(3);
  const [wittyLevel, setWittyLevel] = useState<number>(4);
  const [dominanceLevel, setDominanceLevel] = useState<number>(5);
  const [mysteryLevel, setMysteryLevel] = useState<number>(4);
  const [speed, setSpeed] = useState<ConversationSpeed>('normal');

  const fileInputRef = useRef<HTMLInputElement>(null);
  const chatContainerRef = useRef<HTMLDivElement>(null);

  const activeTabData = TABS.find(t => t.id === activeTab)!;

  // --- HELPERS ---

  const updateActiveProfileMessages = (newMessages: Message[]) => {
    setProfiles(prev => prev.map(p => 
      p.id === activeProfileId ? { ...p, messages: newMessages, metrics: { ...p.metrics, lastInteraction: Date.now() } } : p
    ));
  };

  const handleProfileStyleChange = (styleId: string) => {
    const p = PROFILES_STYLES.find(pr => pr.id === styleId);
    if (p) {
      setActiveProfileStyle(styleId);
      setFlirtLevel(p.flirt);
      setWittyLevel(p.witty);
      setDominanceLevel(p.dominance);
      setMysteryLevel(p.mystery);
      setSpeed(p.speed);
    }
  };

  useEffect(() => {
    if (chatContainerRef.current) {
      chatContainerRef.current.scrollTop = chatContainerRef.current.scrollHeight;
    }
  }, [activeProfile.messages, status]);

  const handleImageUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (file) {
      const reader = new FileReader();
      reader.onloadend = () => {
        setSelectedImage(reader.result as string);
      };
      reader.readAsDataURL(file);
    }
  };

  const handleReset = () => {
    updateActiveProfileMessages([]);
    setInputText('');
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    setStatus(ProcessingState.IDLE);
    handleProfileStyleChange('CALM');
  };

  const handleSubmit = async (e?: React.FormEvent) => {
    if (e) e.preventDefault();
    if ((!inputText.trim() && !selectedImage) || status !== ProcessingState.IDLE) return;

    const newMessage: Message = {
      id: Date.now().toString(),
      role: 'user',
      content: inputText,
      image: selectedImage || undefined,
      timestamp: Date.now(),
      mode: activeTab,
      flirtLevel,
      wittyLevel,
      dominanceLevel,
      mysteryLevel,
      speed
    };

    const updatedMessages = [...activeProfile.messages, newMessage];
    updateActiveProfileMessages(updatedMessages);
    setInputText('');
    setSelectedImage(null);
    if (fileInputRef.current) fileInputRef.current.value = '';
    setStatus(ProcessingState.ANALYZING);

    try {
      const analysis = await analyzeContent(
        newMessage.content || '', 
        newMessage.image,
        activeTab,
        flirtLevel,
        wittyLevel,
        dominanceLevel,
        mysteryLevel,
        speed,
        settings,
        activeProfile
      );

      const responseMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        analysis: analysis,
        timestamp: Date.now(),
      };

      // Update metrics based on analysis
      setProfiles(prev => prev.map(p => 
        p.id === activeProfileId ? { 
          ...p, 
          messages: [...updatedMessages, responseMessage], 
          metrics: { 
            interest: analysis.interestLevel, 
            risk: analysis.risk, 
            lastInteraction: Date.now() 
          } 
        } : p
      ));

      setStatus(ProcessingState.IDLE);
    } catch (error) {
      console.error(error);
      setStatus(ProcessingState.ERROR);
      // Fallback message
      const errMessage: Message = {
        id: (Date.now() + 1).toString(),
        role: 'assistant',
        content: "Sistema instável. Tente novamente.",
        timestamp: Date.now(),
      };
      updateActiveProfileMessages([...updatedMessages, errMessage]);
      setTimeout(() => setStatus(ProcessingState.IDLE), 3000);
    }
  };

  const handleRunLab = async (messageId: string) => {
    const msgIndex = activeProfile.messages.findIndex(m => m.id === messageId);
    if (msgIndex === -1) return;

    const targetMsg = activeProfile.messages[msgIndex];
    if (!targetMsg.analysis || targetMsg.labResult) return; // Already has result or no analysis

    // Find context (user input that triggered this)
    const contextMsg = activeProfile.messages[msgIndex - 1];
    const contextText = contextMsg?.content || (contextMsg?.image ? "Image Analysis" : "Unknown Context");

    setStatus(ProcessingState.CALCULATING);
    try {
      const labResult = await runLaboratory(contextText, targetMsg.analysis, activeProfile);

      const newMessages = [...activeProfile.messages];
      newMessages[msgIndex] = { ...targetMsg, labResult: labResult };
      updateActiveProfileMessages(newMessages);
    } catch (e) {
      console.error(e);
    } finally {
      setStatus(ProcessingState.IDLE);
    }
  };

  // --- THEMING ---
  const getAccentColor = () => {
    switch (settings.accentColor) {
      case 'red': return 'text-red-500 border-red-500 bg-red-500/10';
      case 'blue': return 'text-blue-500 border-blue-500 bg-blue-500/10';
      default: return 'text-crystal-gold border-crystal-gold bg-crystal-gold/10';
    }
  };

  const getAccentText = () => {
    switch (settings.accentColor) {
      case 'red': return 'text-red-500';
      case 'blue': return 'text-blue-500';
      default: return 'text-crystal-gold';
    }
  };

  const getAccentBg = () => {
     switch (settings.accentColor) {
      case 'red': return 'bg-red-500';
      case 'blue': return 'bg-blue-500';
      default: return 'bg-crystal-gold';
    }
  };

  if (isSettingsOpen) {
    return (
      <SettingsView 
        settings={settings} 
        updateSettings={setSettings} 
        onClose={() => setIsSettingsOpen(false)} 
        accentColor={settings.accentColor}
      />
    );
  }

  if (isProfilesOpen) {
    return (
      <ProfilesView
        profiles={profiles}
        activeProfileId={activeProfileId}
        onSelectProfile={(id) => { setActiveProfileId(id); setIsProfilesOpen(false); }}
        onAddProfile={(name, desc) => setProfiles(prev => [...prev, { id: Date.now().toString(), name, description: desc, messages: [], metrics: { interest: 'Oscilante', risk: 'Baixo', lastInteraction: Date.now() }, behavioralPattern: '' }])}
        onDeleteProfile={(id) => {
          setProfiles(prev => prev.filter(p => p.id !== id));
          if (activeProfileId === id) setActiveProfileId('general');
        }}
      />
    );
  }

  return (
    <div className={`flex flex-col h-screen ${settings.theme === 'ultra-dark' ? 'bg-[#000000]' : 'bg-[#050505]'} text-gray-200 font-sans overflow-hidden transition-colors duration-500 relative`}>

      {helpMode && <HelpModal mode={helpMode} onClose={() => setHelpMode(null)} />}

      {/* HEADER */}
      <header className={`flex-none ${settings.theme === 'ultra-dark' ? 'bg-[#050505]' : 'bg-[#0a0a0a]'} z-20 pt-4 pb-2 px-4 flex justify-between items-center border-b border-crystal-800`}>
        <div className="flex items-center space-x-3" onClick={() => setIsProfilesOpen(true)}>
          <div className="flex flex-col">
            <div className="flex items-center space-x-2">
              <InfinityIcon className={getAccentText()} size={20} />
              <h1 className="text-sm font-bold tracking-[0.2em] font-mono text-white leading-none">
                {activeProfile.name.toUpperCase()}
              </h1>
            </div>
            <p className={`text-[8px] font-mono tracking-widest mt-0.5 opacity-70 ${getAccentText()}`}>
              {activeProfile.id === 'general' ? 'CRYSTAL PRIME OS' : activeProfile.description}
            </p>
          </div>
        </div>
        <div className="flex items-center space-x-2">
           <button onClick={() => setHelpMode(activeTab)} className="text-gray-600 hover:text-white transition-colors p-2">
             <HelpCircle size={18} />
          </button>
          <button onClick={() => setIsSettingsOpen(true)} className="text-gray-600 hover:text-gray-300 transition-colors p-2">
             <Settings size={18} />
          </button>
        </div>
      </header>

      {/* TABS SCROLLBAR */}
      <div className={`flex-none ${settings.theme === 'ultra-dark' ? 'bg-[#050505]' : 'bg-[#080808]'} border-b border-crystal-800 overflow-x-auto py-3 px-2 flex space-x-2 z-10`}>
        {TABS.map((tab) => {
          const isActive = activeTab === tab.id;
          const Icon = tab.icon;
          return (
            <button
              key={tab.id}
              onClick={() => setActiveTab(tab.id)}
              className={`flex-none flex items-center space-x-2 px-3 py-2 rounded-full border transition-all duration-300 ${
                isActive 
                  ? `${getAccentColor()} shadow-[0_0_10px_rgba(0,0,0,0.5)]` 
                  : 'bg-[#0a0a0a] border-crystal-800 text-gray-500 hover:text-gray-300'
              }`}
            >
              <Icon size={14} />
              <span className="text-[10px] font-bold uppercase tracking-wider font-mono">
                {tab.label}
              </span>
            </button>
          );
        })}
      </div>

      {/* CHAT AREA */}
      <main ref={chatContainerRef} className={`flex-1 overflow-y-auto p-4 space-y-8 scroll-smooth ${settings.theme === 'ultra-dark' ? 'bg-[#000000]' : 'bg-[#050505]'}`}>
        {activeProfile.messages.length === 0 && (
          <div className="h-full flex flex-col items-center justify-center opacity-30 pointer-events-none p-8">
            <activeTabData.icon size={48} className="mb-6 text-gray-800" />
            <div className="text-center space-y-2">
              <h2 className="text-base font-mono font-bold text-gray-600 tracking-[0.2em]">{activeTabData.desc.toUpperCase()}</h2>
              <p className="text-xs text-gray-700 font-light">
                 {activeProfile.id === 'general' ? 'Aguardando Input...' : `Histórico de ${activeProfile.name} iniciado.`}
              </p>
            </div>

             <div className="mt-12 text-[10px] font-mono text-gray-800 tracking-widest uppercase">
              Amorim Inc • Inteligência Social
            </div>
          </div>
        )}

        {activeProfile.messages.map((msg) => (
          <div key={msg.id} className={`flex flex-col ${msg.role === 'user' ? 'items-end' : 'items-start'} ${settings.animations ? 'animate-fade-in' : ''}`}>
            {msg.role === 'user' && (
              <div className="max-w-[85%] text-right">
                 {msg.image && (
                  <div className="mb-2 rounded border border-crystal-800 inline-block overflow-hidden">
                    <img src={msg.image} alt="Upload" className="max-h-48 object-cover opacity-90" />
                  </div>
                )}
                {msg.content && (
                  <div className="bg-[#121212] border border-crystal-800 text-gray-300 px-4 py-2 rounded-2xl rounded-tr-sm inline-block">
                    <p className="text-xs font-mono">{msg.content}</p>
                  </div>
                )}
                {msg.mode && (
                  <div className="flex items-center justify-end space-x-2 mt-1 opacity-40">
                    <span className="text-[8px] font-mono text-gray-600 uppercase tracking-wider">{msg.speed}</span>
                  </div>
                )}
              </div>
            )}

            {msg.role === 'assistant' && (
              <div className="w-full">
                {msg.content ? (
                   <div className="bg-red-950/20 border border-red-900/30 text-red-400 px-4 py-3 rounded-lg text-xs font-mono max-w-md">
                     {msg.content}
                   </div>
                ) : msg.analysis && (
                  <>
                    <div className="max-w-md relative">
                      <AnalysisView analysis={msg.analysis} />

                      {/* Lab Trigger */}
                      {!msg.labResult && (
                        <button 
                          onClick={() => handleRunLab(msg.id)}
                          className="absolute top-4 right-4 text-gray-500 hover:text-crystal-gold transition-colors p-1"
                          title="Abrir Laboratório"
                        >
                          <FlaskConical size={14} />
                        </button>
                      )}
                    </div>

                    {/* Lab Result View */}
                    {msg.labResult && (
                      <div className="max-w-md mb-6">
                        <LaboratoryView simulation={msg.labResult} />
                      </div>
                    )}

                    {/* Responses Scroll */}
                    <div className="-mx-2">
                      <ResponseOptions responses={msg.analysis.responses} />
                    </div>
                  </>
                )}
              </div>
            )}
          </div>
        ))}

        {status !== ProcessingState.IDLE && status !== ProcessingState.ERROR && (
           <div className="flex items-center space-x-2 pl-2 opacity-50">
             <div className={`w-1 h-1 rounded-full animate-bounce ${getAccentBg()}`}></div>
             <div className={`w-1 h-1 rounded-full animate-bounce delay-100 ${getAccentBg()}`}></div>
             <div className={`w-1 h-1 rounded-full animate-bounce delay-200 ${getAccentBg()}`}></div>
             {status === ProcessingState.CALCULATING && <span className="text-[9px] font-mono text-gray-500 ml-2 uppercase animate-pulse">Simulando...</span>}
           </div>
        )}
      </main>

      {/* FOOTER */}
      <footer className={`flex-none ${settings.theme === 'ultra-dark' ? 'bg-[#050505]' : 'bg-[#0a0a0a]'} border-t border-crystal-800 shadow-[0_-10px_40px_rgba(0,0,0,0.8)] z-20`}>

        {/* PROFILES & SLIDERS */}
        <div className="px-5 py-4 border-b border-crystal-800/50">

          {/* Profiles Styles */}
          <div className="flex space-x-3 mb-4 overflow-x-auto pb-2">
             {PROFILES_STYLES.map(p => {
               const Icon = p.icon;
               const isActive = activeProfileStyle === p.id;
               return (
                 <button
                    key={p.id}
                    onClick={() => handleProfileStyleChange(p.id)}
                    className={`flex-none flex items-center space-x-1.5 px-3 py-1.5 rounded-full border text-[10px] font-mono uppercase tracking-wide transition-all ${
                      isActive 
                      ? `${getAccentColor()}` 
                      : 'bg-transparent border-crystal-800 text-gray-600 hover:border-gray-600'
                    }`}
                 >
                   <Icon size={10} />
                   <span>{p.label}</span>
                 </button>
               )
             })}
          </div>

          {/* New Grid Layout for Advanced Sliders */}
          <div className="grid grid-cols-2 gap-x-6 gap-y-3">
            {/* Flirt */}
            <div className="space-y-1">
              <div className="flex justify-between text-[8px] font-mono text-gray-500 uppercase">
                <span>Flirt</span>
                <span className={getAccentText()}>{flirtLevel}</span>
              </div>
              <input type="range" min="0" max="10" value={flirtLevel} onChange={(e) => setFlirtLevel(parseInt(e.target.value))} className={`w-full h-1 bg-crystal-800 rounded-lg appearance-none cursor-pointer accent-${settings.accentColor === 'gold' ? 'crystal-gold' : settings.accentColor + '-500'}`} />
            </div>

            {/* Dominance */}
            <div className="space-y-1">
              <div className="flex justify-between text-[8px] font-mono text-gray-500 uppercase">
                <span>Dominância</span>
                <span className={getAccentText()}>{dominanceLevel}</span>
              </div>
              <input type="range" min="0" max="10" value={dominanceLevel} onChange={(e) => setDominanceLevel(parseInt(e.target.value))} className="w-full h-1 bg-crystal-800 rounded-lg appearance-none cursor-pointer" />
            </div>

             {/* Mystery */}
             <div className="space-y-1">
              <div className="flex justify-between text-[8px] font-mono text-gray-500 uppercase">
                <span>Mistério</span>
                <span className={getAccentText()}>{mysteryLevel}</span>
              </div>
              <input type="range" min="0" max="10" value={mysteryLevel} onChange={(e) => setMysteryLevel(parseInt(e.target.value))} className="w-full h-1 bg-crystal-800 rounded-lg appearance-none cursor-pointer" />
            </div>

            {/* Speed Toggle */}
            <div className="flex items-end h-full pb-1">
               <button 
                 onClick={() => setSpeed(s => s === 'short' ? 'normal' : s === 'normal' ? 'fluid' : 'short')}
                 className="w-full flex justify-between items-center bg-crystal-800/50 px-2 py-1 rounded border border-crystal-800 hover:border-crystal-600 text-[9px] font-mono text-gray-400 uppercase"
               >
                 <span>Velocidade</span>
                 <span className={getAccentText()}>{speed === 'short' ? 'Curta' : speed === 'normal' ? 'Normal' : 'Fluida'}</span>
               </button>
            </div>
          </div>
        </div>

        {/* INPUT */}
        <div className="p-3 max-w-4xl mx-auto">
          {selectedImage && (
            <div className="flex items-center bg-[#121212] p-2 rounded border border-crystal-800 w-fit mb-2">
              <img src={selectedImage} alt="Preview" className="h-8 w-8 object-cover rounded mr-2 opacity-80" />
              <button onClick={() => {setSelectedImage(null); if(fileInputRef.current) fileInputRef.current.value=''}} className="text-gray-600 hover:text-white">
                <X size={14} />
              </button>
            </div>
          )}

          <form onSubmit={handleSubmit} className="flex items-center space-x-2">
            <input 
              type="file" 
              accept="image/*" 
              ref={fileInputRef}
              onChange={handleImageUpload}
              className="hidden" 
            />

            <button 
              type="button" 
              onClick={() => setIsProfilesOpen(true)}
              className={`p-3 rounded-xl bg-[#0a0a0a] border border-crystal-800 text-gray-500 transition-all hover:text-white hover:border-white/20`}
            >
              <Users size={18} />
            </button>

             <button 
              type="button" 
              onClick={() => fileInputRef.current?.click()}
              className={`p-3 rounded-xl bg-[#0a0a0a] border border-crystal-800 text-gray-500 transition-all hover:text-white`}
              disabled={status !== ProcessingState.IDLE}
            >
              <ImageIcon size={18} />
            </button>

            <div className="flex-1 relative">
              <input
                type="text"
                value={inputText}
                onChange={(e) => setInputText(e.target.value)}
                placeholder={activeTab === 'STORY_REPLY' ? "Anexar Story ou descrever..." : `Comando para modo ${activeTabData.label}...`}
                className="w-full bg-[#0a0a0a] text-gray-200 placeholder-gray-700 rounded-xl py-3 px-4 border border-crystal-800 focus:border-white/20 focus:ring-1 focus:ring-white/10 focus:outline-none transition-all font-sans text-sm"
                disabled={status !== ProcessingState.IDLE}
              />
            </div>

            <button 
              type="submit" 
              className={`p-3 rounded-xl transition-all flex items-center justify-center border ${
                (!inputText && !selectedImage) || status !== ProcessingState.IDLE
                  ? 'bg-[#0a0a0a] border-crystal-800 text-gray-700' 
                  : `${getAccentBg()} text-black border-transparent hover:opacity-90 shadow-lg`
              }`}
              disabled={(!inputText && !selectedImage) || status !== ProcessingState.IDLE}
            >
              {status === ProcessingState.IDLE ? <Send size={18} /> : <div className="w-4 h-4 border-2 border-black/30 border-t-black rounded-full animate-spin"></div>}
            </button>
          </form>

          <div className="flex justify-between items-center mt-2 px-2">
            <span className="text-[8px] text-gray-800 font-mono tracking-widest uppercase">
              Amorim Inc v3.0 • Premium
            </span>
             <span className={`text-[8px] font-mono tracking-widest uppercase animate-pulse ${getAccentText()} opacity-50`}>
              ● Online
            </span>
          </div>
        </div>
      </footer>
    </div>
  );
};

